package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Sealed, owned evaluation datasets. Expected answers and observations are encrypted at rest. */
final class AssistantEvaluations {
 private AssistantEvaluations() {}
 static int integer(Object value,int low,int high){require(value instanceof Integer,"Use an integer");int n=(Integer)value;require(n>=low && n<=high,"Integer exceeds the allowed range");return n;}
 static Map<String,Object> directory(Store.Db db)throws Exception{Service.requireAccountAdministrator(db,db.viewerId);return map("suites",db.all("SELECT suite_id,name,version,cohort,created FROM os_ai_evaluation WHERE owner_id=? ORDER BY created DESC,suite_id LIMIT 20",db.viewerId));}
 static Map<String,Object> owned(Store.Db db,String id)throws Exception{Service.requireAccountAdministrator(db,db.viewerId);var row=db.one("SELECT * FROM os_ai_evaluation WHERE suite_id=? AND owner_id=?",id,db.viewerId);if(row==null)throw new Failure(404,"Evaluation suite not found");return row;}
 static Map<String,Object> data(Store store,Store.Db db,Map<String,Object> row)throws Exception{var data=Outbox.decrypt(store.secret,row.get("envelope").toString());for(var item:objects(data.get("cases"))){var source=object(KnowledgeQuestions.context(store,db,item.get("article_id").toString()).get("source"));if(!item.get("fingerprint").equals(DigestUtils.sha256Hex(JSON.writeValueAsString(source))))throw new Failure(409,"Evaluation source changed; create a fresh suite or delete this one");}return data;}
 static Map<String,Object> page(Store store,Store.Db db,String id)throws Exception{var row=owned(db,id);var data=data(store,db,row);row.remove("owner_id");row.remove("envelope");row.putAll(data);for(var run:objects(row.get("runs")))run.remove("proof");row.put("preview",null);return row;}
 static Map<String,Object> create(Store store,Store.Db db,Object input)throws Exception{
  Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);require(body.keySet().equals(Set.of("name","version","cohort","provenance","latency_budget_ms","minimum_pass_percent","cases")),"Provide the sealed dataset fields only");String name=WorkJobs.text(body.get("name"),160),version=WorkJobs.text(body.get("version"),80),cohort=WorkJobs.text(body.get("cohort"),12),provenance=WorkJobs.text(body.get("provenance"),2000);require(Set.of("development","held_out").contains(cohort),"Choose development or held_out");int latency=integer(body.get("latency_budget_ms"),1,30000),minimum=integer(body.get("minimum_pass_percent"),0,100);require(body.get("cases") instanceof List<?>,"Provide an array of cases");var raw=(List<?>)body.get("cases");require(!raw.isEmpty() && raw.size()<=10,"Provide one to ten cases");var cases=new ArrayList<Map<String,Object>>();for(Object value:raw){var item=object(value);require(item.keySet().equals(Set.of("article_id","question","expected_answer")),"Provide article_id, question and expected_answer");String article=WorkJobs.text(item.get("article_id"),32);var source=object(KnowledgeQuestions.context(store,db,article).get("source"));cases.add(map("article_id",article,"question",WorkJobs.text(item.get("question"),2000),"expected_answer",WorkJobs.text(item.get("expected_answer"),8000),"source_version",source.get("version"),"fingerprint",DigestUtils.sha256Hex(JSON.writeValueAsString(source))));}require(db.count("SELECT COUNT(*) FROM os_ai_evaluation WHERE owner_id=?",db.viewerId)<20 && db.count("SELECT COUNT(*) FROM os_ai_evaluation")<5000,"Evaluation suite capacity reached; delete an older suite");String id=Values.id();var data=map("provenance",provenance,"latency_budget_ms",latency,"minimum_pass_percent",minimum,"cases",cases,"runs",List.of());String hash=DigestUtils.sha256Hex(JSON.writeValueAsString(map("version",version,"cohort",cohort,"dataset",data)));db.update("INSERT INTO os_ai_evaluation(suite_id,owner_id,name,version,cohort,dataset_hash,envelope,created) VALUES(?,?,?,?,?,?,?,?)",id,db.viewerId,name,version,cohort,hash,Outbox.encrypt(store.secret,JSON.writeValueAsString(data)),now());SecurityEvents.record(db,db.viewerId,db.viewerId,"ai.evaluation_sealed",map("suite_id",id,"dataset_hash",hash,"cases",cases.size()));return page(store,db,id);
 }
 static Map<String,Object> command(Store store,Store.Db db,String id,Object input)throws Exception{
  var row=owned(db,id);var body=object(input);String operation=WorkJobs.text(body.get("operation"),12);if(operation.equals("delete")){require(body.keySet().equals(Set.of("operation","confirm")) && Boolean.TRUE.equals(body.get("confirm")),"Confirm deleting the evaluation suite and its runs");db.update("DELETE FROM os_ai_evaluation WHERE suite_id=?",id);SecurityEvents.record(db,db.viewerId,db.viewerId,"ai.evaluation_deleted",map("suite_id",id));return map("deleted",true);}var data=data(store,db,row);var preview=EvaluationRuns.command(store,db,row,data,body);db.update("UPDATE os_ai_evaluation SET envelope=? WHERE suite_id=?",Outbox.encrypt(store.secret,JSON.writeValueAsString(data)),id);var result=page(store,db,id);result.put("preview",preview);return result;
 }
 static Map<String,Object> form(Map<String,String> arguments){var body=new LinkedHashMap<String,Object>(arguments);body.remove("csrf");for(String key:List.of("latency_budget_ms","minimum_pass_percent","case"))if(body.containsKey(key))body.put(key,Service.number(body.get(key).toString(),0,30000));for(String key:List.of("confirm","allow_external","acceptable","grounded","correction_needed"))if(body.containsKey(key))body.put(key,"true".equals(body.get(key)));if(body.containsKey("cases")){try{body.put("cases",JSON.readValue(body.get("cases").toString(),Object.class));}catch(tools.jackson.core.JacksonException invalid){throw new Failure(400,"Invalid evaluation cases JSON");}}return body;}
}
